// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }

    // fuzz the callee selector/data length seed so fuzzer explores calldata; we must at least take one param
    function testFuzz_property(bytes memory data) public {
        // Deploy a callee that ALWAYS reverts on fallback to trigger the difference
        Reverter rev = new Reverter();

        // Try calling forward; reference implementation should revert because it requires the inner call to succeed.
        bool ok;
        try c.forward(address(rev), data) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: for ANY calldata, forwarding to a callee whose fallback reverts must cause c.forward to revert.
        // So ok must be false for all inputs. The buggy mutant (which omits the require) will make ok == true
        // for some input (in fact for all inputs) and thus violate this assertion.
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert in callee");
    }
}
